// src/components/AdminDashboard.jsx

import React, { useEffect, useState } from 'react';
import axios from 'axios';
import './AdminDashboard.css';
import { Link, useHistory } from 'react-router-dom';

const AdminDashboard = () => {
  const [eventCount, setEventCount] = useState(0);
  const [userCount, setUserCount] = useState(0);
  const [feedbackCount, setFeedbackCount] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  
  const history = useHistory();

  useEffect(() => {
    const fetchDashboardData = async () => {
      try {
        const token = localStorage.getItem('token');
        const response = await axios.get('http://localhost:5000/api/admin/dashboard', {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });

        const { events, users, feedback } = response.data;
        setEventCount(events);
        setUserCount(users);
        setFeedbackCount(feedback);
      } catch (err) {
        console.error('Error fetching dashboard data:', err);
        setError('Failed to load dashboard data. Please try again later.');
      } finally {
        setLoading(false);
      }
    };

    fetchDashboardData();
  }, []);

  const handleManageUsers = () => {
    history.push('/admin/users');
  };

  const handleFeedbackClick = () => {
    alert('Displaying feedback...');
    history.push('/admin/feedback');
  };

  return (
    <div className="admin-dashboard-container">
      <h2>Admin Dashboard</h2>

      {loading && <p>Loading dashboard data...</p>}
      {error && <p className="error-message">{error}</p>}

      <div className="dashboard-stats">
        <div className="stat-card">
          <h3>Total Events</h3>
          <p>{eventCount}</p>
          <Link to="/admin/events" className="btn">Manage Events</Link>
        </div>
        <div className="stat-card">
          <h3>Total Users</h3>
          <p>{userCount}</p>
          <button onClick={handleManageUsers} className="btn">Manage Users</button>
        </div>
        <div className="stat-card">
          <h3>Total Feedback</h3>
          <p>{feedbackCount}</p>
          <button onClick={handleFeedbackClick} className="btn">View Feedback</button>
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;




